// Obtém o número do primeiro input
const phone = $input.first().json.telefone || null;

if (phone) {
    const trimmed = phone.toString().trim();

    // Verifica se é número de Portugal (prefixo +351)
    if (trimmed.startsWith("+351")) {
        const sanitized = trimmed.replace(/[^\d]/g, ""); // remove símbolos
        return [{ json: { phone: sanitized, country: "PT" } }];
    }

    // Caso contrário, assume-se que é Brasil
    let sanitizedPhone = trimmed.replace(/[^\d]/g, "");

    // Adiciona DDI 55 se for número nacional (10 ou 11 dígitos)
    if (sanitizedPhone.length === 10 || sanitizedPhone.length === 11) {
        sanitizedPhone = "55" + sanitizedPhone;
    }

    return [{ json: { phone: sanitizedPhone, country: "BR" } }];
}

// Retorna array vazio se o número não for válido
return [];

